      // --- during-gesture screenshot --------------------------------------
      final heroSurface = find.byType(HeroFeedbackSurface);
      expect(heroSurface, findsOneWidget);

      final gesture =
          await tester.startGesture(tester.getCenter(heroSurface));
      await gesture.moveBy(const Offset(180, 0));
      await tester.pump();

      // Crumb preview should replace the folder readout while scrubbing.
      final crumbPreviewFinder =
          find.byKey(const ValueKey('void-seek-crumb-preview'));
      expect(crumbPreviewFinder, findsOneWidget);
      final crumbText = tester.widget<Text>(crumbPreviewFinder).data ?? '';
      expect(crumbText, contains(' / 1:00'));

      // Center seek HUD must stay hidden on Linux.
      expect(find.byKey(HeroFeedbackSurface.seekHudKey), findsNothing);

      final duringPath = '.tmp/seek_preview_during.png';
      await _capturePng(
        tester: tester,
        boundaryKey: boundaryKey,
        filePath: duringPath,
      );

      // --- post-gesture screenshot ----------------------------------------
      await gesture.up();
      await tester.pumpAndSettle();

      // Temporary preview clears right after release.
      expect(
        find.byKey(const ValueKey('void-seek-crumb-preview')),
        findsNothing,
      );
      expect(find.text('music'), findsOneWidget);
      expect(find.byKey(HeroFeedbackSurface.seekHudKey), findsNothing);

      final postPath = '.tmp/seek_preview_post.png';
      await _capturePng(
        tester: tester,
        boundaryKey: boundaryKey,
        filePath: postPath,
      );


